import React, { useState, useEffect } from "react";
import "./taskflow.css";

const API_URL = "http://localhost:8000/api";

function formatDate(iso) {
    return new Date(iso).toLocaleDateString("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
    });
}

function Taskflow() {
    const [search, setSearch] = useState("");
    const [newTask, setNewTask] = useState("");
    const [selectedId, setSelectedId] = useState(null);
    const [tasks, setTasks] = useState([]);
    const [error, setError] = useState("");

    // Load tasks on first render
    useEffect(() => {
        async function loadTasks() {
            try {
                const res = await fetch(`${API_URL}/tasks`);
                if (!res.ok) throw new Error("Failed to load tasks");
                const json = await res.json();
                setTasks(json.data);
            } catch (err) {
                setError(err.message);
            }
        }
        loadTasks();
    }, []);

    async function addTask() {
        if (newTask.trim() === "") return;

        try {
            const res = await fetch(`${API_URL}/tasks`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ title: newTask }),
            });
            if (!res.ok) throw new Error("Failed to add task");
            const created = await res.json();
            setTasks([...tasks, created]);
            setNewTask("");
            setError("");
        } catch (err) {
            setError(err.message);
        }
    }

    function selectTask(id) {
        setSelectedId(selectedId === id ? null : id);
    }

    async function updateTask(id, changes) {
        try {
            const res = await fetch(`${API_URL}/tasks/${id}`, {
                method: "PATCH",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(changes),
            });
            if (!res.ok) throw new Error("Failed to update task");
            const updated = await res.json();
            setTasks(tasks.map((t) => (t.id === id ? updated : t)));
            setError("");
        } catch (err) {
            setError(err.message);
        }
    }

    function toggleCompleted(id, currentValue) {
        updateTask(id, { completed: !currentValue });
    }

    function editTask(id, oldTitle) {
        const title = prompt("Edit task:", oldTitle);
        if (title === null || title.trim() === "") return;
        updateTask(id, { title });
    }

    async function deleteTask(id) {
        try {
            const res = await fetch(`${API_URL}/tasks/${id}`, { method: "DELETE" });
            if (!res.ok) throw new Error("Failed to delete task");
            setTasks(tasks.filter((t) => t.id !== id));
            if (selectedId === id) setSelectedId(null);
            setError("");
        } catch (err) {
            setError(err.message);
        }
    }

    const filteredTasks = tasks.filter((t) =>
        t.title.toLowerCase().includes(search.toLowerCase())
    );

    const selectedTask = tasks.find((t) => t.id === selectedId);

    return (
        <div>
            <header className="header">
                <h1>TaskFlow</h1>
            </header>

            {error && <p className="error">{error}</p>}

            <div className="card">
                <h2>List View</h2>

                <input
                    className="text-box"
                    type="text"
                    placeholder="Search tasks..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />

                <div className="add-row">
                    <input
                        className="text-box"
                        type="text"
                        placeholder="Add a new task..."
                        value={newTask}
                        onChange={(e) => setNewTask(e.target.value)}
                    />
                    <button className="add-btn" onClick={addTask}>Add</button>
                </div>

                {filteredTasks.map((task) => (
                    <div className="task" key={task.id}>
                        <div>
                            <input
                                type="checkbox"
                                checked={selectedId === task.id}
                                onChange={() => selectTask(task.id)}
                            />
                            <span className={task.completed ? "title done" : "title"}>
                                {task.title}
                            </span>
                        </div>
                        <div className="task-buttons">
                            <button onClick={() => editTask(task.id, task.title)}>Edit</button>
                            <button onClick={() => deleteTask(task.id)}>Delete</button>
                        </div>
                    </div>
                ))}
            </div>

            {selectedTask && (
                <div className="card">
                    <h2>Detail View</h2>

                    <p className="label">Title</p>
                    <p className="value">{selectedTask.title}</p>

                    <p className="label">Status</p>
                    <p className="value">{selectedTask.completed ? "Completed" : "Pending"}</p>

                    <p className="label">Created</p>
                    <p className="value">{formatDate(selectedTask.createdAt)}</p>

                    <div className="task-buttons">
                        <button onClick={() => toggleCompleted(selectedTask.id, selectedTask.completed)}>
                            {selectedTask.completed ? "Mark as Pending" : "Mark as Completed"}
                        </button>
                        <button onClick={() => deleteTask(selectedTask.id)}>Delete</button>
                    </div>
                </div>
            )}
        </div>
    );
}

export default Taskflow;
